def head(title, description, body_class=""):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{html.escape(description)}"><title>{html.escape(title)}</title><link rel="stylesheet" href="assets/style.css"><link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 64 64'%3E%3Crect width='64' height='64' fill='%23156360'/%3E%3Ctext x='12' y='45' fill='white' font-size='40'%3EH%3C/text%3E%3C/svg%3E"></head><body class="{body_class}"><a class="skip" href="#main">Skip to content</a><header class="nav"><a class="brand" href="portfolio.html">HAMZA AFZAL <span aria-hidden="true"> / </span> BACKEND ENGINEERING</a><nav aria-label="Main navigation"><a href="index.html">Research paper</a><a href="portfolio.html">Portfolio</a><a href="{REPO}">Source ↗</a></nav></header>'''

