js = '''const comparison=DATA; const budget=document.getElementById('budget'); function render(){const k=Number(budget.value),d=comparison[k];for(const name of ['model','baseline']){const id=name==='baseline'?'base':'model';document.getElementById(id+'-bar').style.width=(d[name]*100)+'%';document.getElementById(id+'-value').textContent=Math.round(d[name]*100)+'%';}document.getElementById('comparison-caption').textContent=`Precision@${k}: ${Math.round(d.model*k)} observed decline cases for the selected model, versus ${Math.round(d.baseline*k)} for the baseline.`;}budget.addEventListener('change',render);render();'''.replace("DATA", json.dumps(comparison))
